// Bluetooth RGB LED: telefondan renk adı ya da "R,G,B" yaz, LED o renge döner.
// Telefona "Serial Bluetooth Terminal" gibi bir uygulama kur ve KendinYap-RGB cihazına bağlan.
// Not: ledcAttach için Arduino IDE'de ESP32 kart paketi 3.x gerekir.
#include <BluetoothSerial.h>

const char* BT_ADI = "KendinYap-RGB";
const int KIRMIZI_PIN = 18;
const int YESIL_PIN = 19;
const int MAVI_PIN = 21;
const int PWM_FREKANS = 5000;   // Hz
const int PWM_COZUNURLUK = 8;   // 8 bit: 0-255

BluetoothSerial SerialBT;

void renkYap(int r, int g, int b) {
  r = constrain(r, 0, 255);
  g = constrain(g, 0, 255);
  b = constrain(b, 0, 255);
  ledcWrite(KIRMIZI_PIN, r);
  ledcWrite(YESIL_PIN, g);
  ledcWrite(MAVI_PIN, b);
  SerialBT.printf("Renk: %d,%d,%d\n", r, g, b);
  Serial.printf("Renk: %d,%d,%d\n", r, g, b);
}

// "255,120,0" biçimini çözer. Biçim yanlışsa false döner.
bool sayilariCoz(const String& s, int& r, int& g, int& b) {
  int v1 = s.indexOf(',');
  int v2 = s.indexOf(',', v1 + 1);
  if (v1 < 0 || v2 < 0) return false;
  r = s.substring(0, v1).toInt();
  g = s.substring(v1 + 1, v2).toInt();
  b = s.substring(v2 + 1).toInt();
  return true;
}

void komutIsle(String komut) {
  komut.trim();
  komut.toLowerCase();
  if (komut.length() == 0) return;
  Serial.println("Komut: " + komut);
  int r, g, b;
  if (komut == "kirmizi") renkYap(255, 0, 0);
  else if (komut == "yesil") renkYap(0, 255, 0);
  else if (komut == "mavi") renkYap(0, 0, 255);
  else if (komut == "beyaz") renkYap(255, 255, 255);
  else if (komut == "sari") renkYap(255, 160, 0);
  else if (komut == "mor") renkYap(160, 0, 255);
  else if (komut == "kapat") renkYap(0, 0, 0);
  else if (sayilariCoz(komut, r, g, b)) renkYap(r, g, b);
  else SerialBT.println("Komutlar: kirmizi, yesil, mavi, beyaz, sari, mor, kapat ya da R,G,B (0-255)");
}

void setup() {
  Serial.begin(115200);
  ledcAttach(KIRMIZI_PIN, PWM_FREKANS, PWM_COZUNURLUK);
  ledcAttach(YESIL_PIN, PWM_FREKANS, PWM_COZUNURLUK);
  ledcAttach(MAVI_PIN, PWM_FREKANS, PWM_COZUNURLUK);
  ledcWrite(KIRMIZI_PIN, 0);
  ledcWrite(YESIL_PIN, 0);
  ledcWrite(MAVI_PIN, 0);
  SerialBT.begin(BT_ADI);
  Serial.printf("Bluetooth hazir: %s\n", BT_ADI);
}

void loop() {
  if (SerialBT.available()) komutIsle(SerialBT.readStringUntil('\n'));
  delay(20);
}
